@pytest.mark.smoke
@pytest.mark.usefixtures("ai_controls")
def test_alt_i_opens_the_box_in_the_strip_and_esc_gives_the_shell_back(app: App) -> None:
    app.show("terminal")
    app.page.click('[data-pane="terminal"] iframe')
    app.wait_terminal_focus(focused=True)
    app.page.keyboard.press("Alt+i")
    app.strip_box.wait_for(state="visible")
    # in the pane's title strip, not over the shell, with the cursor in it
    assert app.strip_box.evaluate("box => !!box.closest('.console-head')")
    assert app.page.evaluate("() => document.activeElement.className") == "inline-box-input"
    app.page.keyboard.press("Escape")
    app.strip_box.wait_for(state="hidden")
    app.wait_terminal_focus(focused=True)
    app.page.keyboard.type("echo back-in-the-shell")
    app.wait_terminal_text("echo back-in-the-shell")


@pytest.mark.usefixtures("ai_controls")
def test_the_strips_ai_button_and_alt_i_again_both_close_the_box(app: App) -> None:
    app.show("terminal")
    button = app.page.locator('[data-pane="terminal"] [data-inline-ai]')
    button.click()
    app.strip_box.wait_for(state="visible")
    app.page.keyboard.press("Alt+i")  # in the box: closes it, as in a cell
    app.strip_box.wait_for(state="hidden")
    button.click()
    app.strip_box.wait_for(state="visible")
    button.click()
    app.strip_box.wait_for(state="hidden")


@pytest.mark.usefixtures("ai_controls")
def test_an_ask_is_refused_while_a_full_screen_program_has_the_terminal(app: App) -> None:
    # the page refuses before asking the AI: a paste would go into the program, not a prompt
    app.show("terminal")
    app.page.click('[data-pane="terminal"] iframe')
    app.wait_terminal_focus(focused=True)
    app.page.keyboard.type("less /etc/hostname\n")
    app.terminal().wait_for_function("() => window.smashTerminal.text().includes('(END)')")
    app.page.keyboard.press("Alt+i")
    app.strip_box.wait_for(state="visible")
    app.page.keyboard.type("list the files here")
    app.page.keyboard.press("Enter")
    status = app.strip_box.locator(".inline-box-status")
    status.filter(has_text="a full-screen program is running").wait_for()
    assert "is-error" in status.get_attribute("class")
    app.page.keyboard.press("Escape")
    app.wait_terminal_focus(focused=True)
    app.page.keyboard.press("q")  # leave less


@pytest.mark.smoke
def test_the_apps_paste_is_typed_at_the_prompt_and_not_run(app: App) -> None:
    # what the AI's command goes through: typed, and you press Enter
    app.show("terminal")
    app.terminal()
    answer = app.page.evaluate(
        """() => new Promise((done) => {
             const frame = document.querySelector('[data-pane="terminal"] iframe');
             window.addEventListener('message', (e) => e.data?.type === 'delulu-ask-answer' && done(e.data));
             frame.contentWindow.postMessage({ type: 'delulu-ask-paste', id: 7, command: 'echo typed-not-run' }, '*');
           })"""
    )
    assert answer == {"type": "delulu-ask-answer", "id": 7, "pasted": True}
    app.wait_terminal_text("echo typed-not-run")
    # not run: its output would be a line that is only the text
    assert not any(line.strip() == "typed-not-run" for line in app.terminal_text().splitlines())


@pytest.mark.smoke
def test_another_site_cant_frame_the_terminal(browser: Browser, app_url: str, tmp_path: Path) -> None:
    # the hole the review found: a page that framed the shell could send it a paste. Any
    # address but this machine's names is "another site": 127.0.0.2 is one
    assert app_url
    (tmp_path / "index.html").write_text(f'<iframe id="shell" src="{BACKEND}/terminal"></iframe>')
    serve = [sys.executable, "-I", "-m", "http.server", "8765", "--bind", "127.0.0.2", "--directory", str(tmp_path)]
    with subprocess.Popen(serve, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL) as server:
        try:
            page = browser.new_page()
            refused: list[str] = []
            page.on("console", lambda message: "frame-ancestors" in message.text and refused.append(message.text))
            for _ in range(20):  # the server takes a moment to listen
                try:
                    page.goto("http://127.0.0.2:8765/")
                    break
                except Exception:  # noqa: BLE001  # not listening yet
                    page.wait_for_timeout(250)
            page.wait_for_timeout(2500)
            framed = [frame.url for frame in page.frames if "/terminal" in frame.url]
            page.close()
        finally:
            server.terminate()
    assert framed == []
    assert refused, "the browser should say the framing was refused (frame-ancestors)"


def test_the_shell_has_your_theme_colours_and_no_browser_caret(app: App) -> None:
    app.show("terminal")
    theme = app.terminal().evaluate("() => window.smashTerminal.theme()")
    assert theme == terminal.terminal_theme()
    assert len(theme) >= 16  # the ANSI colours too, not only background and text
    style = app.terminal().evaluate(
        "() => { const c = getComputedStyle(document.getElementById('term')); return [c.caretColor, c.outlineStyle]; }"
    )
    assert style == ["rgba(0, 0, 0, 0)", "none"]


def test_the_strips_buttons_stay_at_the_right_whether_the_ai_is_on_or_off(app: App) -> None:
    # the AI's box in the strip is also the space that pushes the buttons right: hidden whole
    # (the AI off), they slid to the left
    app.show("terminal")
    gap = app.page.evaluate(
        """() => { const pane = document.querySelector('[data-pane="terminal"]');
                   const buttons = [...pane.querySelectorAll('.console-head button')];
                   const close = buttons.filter(b => b.getClientRects().length).pop();
                   return pane.getBoundingClientRect().right - close.getBoundingClientRect().right; }"""
    )
    assert gap < 40, f"the strip's last button is {gap:.0f}px from the panel's right edge"
